contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(this).balance);

        c.depositsCount(); if (__ESBMC_reverted()) return;
        c.owner(); if (__ESBMC_reverted()) return;

        uint256 cBalBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 ownerBalBefore = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint256 cBalAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 ownerBalAfter = address(this).balance;

        assert(cBalAfter == 0 && depositsAfter == depositsBefore && ownerAfter == ownerBefore && ownerBalAfter == ownerBalBefore + cBalBefore);
    }

    receive() external payable {}
}

